import { GrandTestQuestion } from "./grandTestMeta";

// FREE Live Mock Test — 19th June 2026. Very-hard AGRICET level, 100 questions
// across all 17 subjects. Includes 48 special-format items: Assertion-Reason,
// two-column & three-column matching, and True/False statement questions.
export const GRAND_TEST_LIVE: GrandTestQuestion[] = [

  // ── AGRONOMY (8) ──
  { id:"gtl_001", qNo:1, subject:"agronomy", question:"In wheat, the most critical stage for irrigation, at which even mild moisture stress causes the maximum reduction in grain yield, is the:", options:["Dough stage", "Crown Root Initiation (CRI) stage", "Late tillering stage", "Milk stage"], correct:1, explanation:"The Crown Root Initiation (CRI) stage (about 20-25 days after sowing) is the most moisture-sensitive stage in wheat. Moisture stress at CRI causes the greatest yield loss because the crown roots that support the entire plant's water and nutrient uptake develop at this time. It is the single most important irrigation if water is limited." },
  { id:"gtl_002", qNo:2, subject:"agronomy", question:"Assertion (A): Puddling is recommended for transplanted lowland rice.\nReason (R): Puddling destroys soil structure and reduces percolation losses of water, helping the soil retain a standing layer of water.", options:["Both A and R are true, and R explains A", "A is false, but R is true", "A is true, but R is false", "Both A and R are true, but R does not explain A"], correct:0, explanation:"Both statements are true and R correctly explains A. Puddling (ploughing the soil in standing water) breaks down soil aggregates and forms a compact, low-permeability layer below the surface. This drastically reduces deep percolation and seepage losses, allowing the field to retain the shallow standing water that lowland rice needs — which is precisely why it is recommended for transplanted rice." },
  { id:"gtl_003", qNo:3, subject:"agronomy", question:"Match List-I (Cropping concept) with List-II (Definition) and select the correct combination:", matchTable:{ headers:["List-I (Cropping concept)", "List-II (Definition)"], rows:[["A. Mixed cropping", "1. Growing two or more crops in definite row proportions in the same field"], ["B. Inter cropping", "2. Growing two or more crops together without any row arrangement"], ["C. Relay cropping", "3. Sowing the succeeding crop before harvesting the standing (preceding) crop"], ["D. Sequence cropping", "4. Growing crops one after another on the same field in a year without overlap"]] }, options:["A-1, B-2, C-4, D-3", "A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-3, B-1, C-2, D-4"], correct:2, explanation:"Mixed cropping = two or more crops grown together with NO row arrangement (2). Inter cropping = two or more crops in DEFINITE row proportions (1). Relay cropping = sowing the next crop INTO the standing crop before its harvest (3). Sequence (multiple) cropping = crops grown one after another in sequence without overlap (4). Hence A-2, B-1, C-3, D-4." },
  { id:"gtl_004", qNo:4, subject:"agronomy", question:"A crop is sown at a spacing of 30 cm between rows and 10 cm between plants. The optimum plant population per hectare is:", options:["1,66,666", "33,333", "83,333", "3,33,333"], correct:3, explanation:"Plant population per hectare = 10,000 m2 / (row spacing x plant spacing in metres) = 10,000 / (0.30 x 0.10) = 10,000 / 0.03 = 3,33,333 plants per hectare." },
  { id:"gtl_005", qNo:5, subject:"agronomy", question:"Consider the following statements about tillage and mulching:\n1. Minimum tillage reduces the number of tillage operations to the minimum necessary for crop establishment.\n2. A stubble/straw mulch chiefly conserves soil moisture by reducing evaporation from the soil surface.\n3. Conservation tillage leaves at least 30% of the soil surface covered with crop residue after sowing.\nWhich of the statements are correct?", options:["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], correct:3, explanation:"All three are correct. Minimum tillage limits cultivation to the minimum needed (1). Mulch reduces direct evaporation from the surface, conserving moisture (2). Conservation tillage, by definition, retains at least 30% residue cover on the soil surface after planting to check erosion (3)." },
  { id:"gtl_006", qNo:6, subject:"agronomy", question:"Striga (witch weed), a partial root parasite that causes serious yield losses, is most destructive in which crop?", options:["Sorghum", "Soybean", "Groundnut", "Rice"], correct:0, explanation:"Striga (witch weed, Striga asiatica) is a partial root parasite - it has chlorophyll but draws water and nutrients from host roots. It is most destructive in sorghum (and also attacks bajra, maize and sugarcane), emerging about 30-40 days after the host germinates." },
  { id:"gtl_007", qNo:7, subject:"agronomy", question:"C4 plants are more efficient than C3 plants under high light and temperature mainly because they have:", options:["A high CO2 compensation point and high photorespiration", "No requirement for the Calvin cycle", "A low CO2 compensation point and negligible photorespiration", "Stomata that remain closed during the day"], correct:2, explanation:"C4 plants (maize, sorghum, sugarcane, bajra) concentrate CO2 in bundle-sheath cells via the Hatch-Slack pathway, giving them a LOW CO2 compensation point (around 0-10 ppm) and essentially negligible photorespiration. This makes them highly efficient in hot, high-light environments, unlike C3 plants which have high photorespiration and a high CO2 compensation point." },
  { id:"gtl_008", qNo:8, subject:"agronomy", question:"The green manure crop that is best suited for in-situ incorporation in waterlogged/lowland rice fields and can fix nitrogen even on its stem is:", options:["Sunhemp (Crotalaria juncea)", "Sesbania rostrata (Dhaincha)", "Cluster bean (Guar)", "Sunflower"], correct:1, explanation:"Sesbania rostrata is unique among green manures because it forms nitrogen-fixing nodules on its STEM as well as its roots, allowing it to fix N even under waterlogged conditions. This makes it especially suited for lowland rice systems where in-situ green manuring is practiced." },

  // ── KHARIF CROPS (6) ──
  { id:"gtl_009", qNo:9, subject:"kharif-crops", question:"The somatic chromosome number (2n) of cultivated rice (Oryza sativa) is:", options:["26", "12", "42", "24"], correct:3, explanation:"Cultivated rice, Oryza sativa, has a somatic chromosome number of 2n = 24 (n = 12). It is a diploid, self-pollinated cereal belonging to the family Poaceae (Gramineae)." },
  { id:"gtl_010", qNo:10, subject:"kharif-crops", question:"Match List-I (Crop) with List-II (Centre of origin) and select the correct combination:", matchTable:{ headers:["List-I (Crop)", "List-II (Centre of origin)"], rows:[["A. Maize", "1. China/South-East Asia"], ["B. Rice", "2. Africa"], ["C. Sorghum", "3. Mexico (Central America)"], ["D. Soybean", "4. China/East Asia"]] }, options:["A-3, B-2, C-1, D-4", "A-1, B-3, C-4, D-2", "A-3, B-1, C-2, D-4", "A-2, B-1, C-3, D-4"], correct:2, explanation:"Maize originated in Mexico/Central America (3); cultivated rice (Oryza sativa) in China/South-East Asia (1); sorghum in Africa (2); soybean in China/East Asia (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gtl_011", qNo:11, subject:"kharif-crops", question:"Assertion (A): Pearl millet (bajra) is naturally a highly cross-pollinated crop.\nReason (R): Pearl millet is protogynous — the stigma emerges and becomes receptive before the anthers of the same spikelet shed pollen.", options:["A is false, but R is true", "Both A and R are true, but R does not explain A", "A is true, but R is false", "Both A and R are true, and R explains A"], correct:3, explanation:"Both true and R explains A. In bajra the stigmas emerge first and are receptive 2-3 days before the anthers of the same head dehisce (protogyny). This temporal separation forces pollen from other plants to effect fertilisation, making bajra a naturally cross-pollinated crop (about 80% outcrossing)." },
  { id:"gtl_012", qNo:12, subject:"kharif-crops", question:"Consider the following statements about sorghum (jowar):\n1. With respect to photoperiod, sorghum is a short-day plant.\n2. Sorghum belongs to the family Poaceae (Gramineae).\n3. Sorghum is botanically a legume that fixes atmospheric nitrogen.\nWhich of the statements are correct?", options:["1 and 3 only", "1 and 2 only", "2 and 3 only", "1, 2 and 3"], correct:1, explanation:"As per the DA-102 notes, sorghum is a short-day plant (flowering and grain formation begin as the day length shortens) and belongs to the family Poaceae / Gramineae. Statement 3 is false - sorghum is a cereal grass, not a nitrogen-fixing legume. Hence only 1 and 2 are correct." },
  { id:"gtl_013", qNo:13, subject:"kharif-crops", question:"Consider the following statements about sugarcane:\n1. 'Bagasse' is the fibrous residue left after juice extraction and is used as boiler fuel.\n2. 'Propping' is the removal of the top growing portion of the cane.\n3. Sugarcane is propagated commercially by setts (stem cuttings), not by seed.\nWhich of the statements are correct?", options:["1 and 3 only", "1, 2 and 3", "2 and 3 only", "1 and 2 only"], correct:0, explanation:"Statements 1 and 3 are correct. Bagasse is the fibrous residue burnt as fuel in mills (1). Sugarcane is propagated commercially by setts/stem cuttings (3). Statement 2 is FALSE — 'propping' is tying/staking canes together to prevent lodging; the removal of the growing top is 'detrashing/topping', not propping." },
  { id:"gtl_014", qNo:14, subject:"kharif-crops", question:"Yellow Mosaic disease, a major constraint in greengram and blackgram, is caused by a virus transmitted by:", options:["Aphids", "Thrips", "White fly (Bemisia tabaci)", "Leafhoppers"], correct:2, explanation:"Mungbean Yellow Mosaic Virus (MYMV), a begomovirus, causes yellow mosaic of greengram and blackgram and is transmitted by the white fly Bemisia tabaci in a persistent manner. Management therefore targets the whitefly vector and use of resistant varieties." },

  // ── RABI CROPS (5) ──
  { id:"gtl_015", qNo:15, subject:"rabi-crops", question:"Vernalization in wheat refers to:", options:["Promotion of flowering by a low-temperature (cold) treatment of seeds or young plants", "Promotion of flowering by exposure to long photoperiods (long days)", "Induction of seed dormancy by exposure to high temperature", "Breaking of seed dormancy by exposure to red light"], correct:0, explanation:"Vernalization is the promotion of flowering by a cold (low-temperature) treatment given to imbibed seeds or young plants. Winter wheat must satisfy this chilling requirement before switching to reproductive growth; spring wheats lack a strong requirement." },
  { id:"gtl_016", qNo:16, subject:"rabi-crops", question:"Match List-I (Rabi/oilseed crop) with List-II (Botanical name) and select the correct combination:", matchTable:{ headers:["List-I (Rabi/oilseed crop)", "List-II (Botanical name)"], rows:[["A. Chickpea", "1. Brassica juncea"], ["B. Mustard", "2. Carthamus tinctorius"], ["C. Safflower", "3. Linum usitatissimum"], ["D. Linseed", "4. Cicer arietinum"]] }, options:["A-4, B-1, C-2, D-3", "A-4, B-2, C-1, D-3", "A-1, B-4, C-2, D-3", "A-4, B-1, C-3, D-2"], correct:0, explanation:"Chickpea = Cicer arietinum (4); Indian mustard = Brassica juncea (1); Safflower = Carthamus tinctorius (2); Linseed/flax = Linum usitatissimum (3). Hence A-4, B-1, C-2, D-3." },
  { id:"gtl_017", qNo:17, subject:"rabi-crops", question:"Assertion (A): Safflower is well suited for cultivation under rainfed, residual-moisture conditions.\nReason (R): Safflower is a shallow-rooted crop that is highly sensitive to even short periods of moisture stress.", options:["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, but R is false", "A is false, but R is true"], correct:2, explanation:"A is TRUE - safflower is a hardy oilseed grown largely on conserved/residual soil moisture in rabi. R is FALSE - safflower is actually DEEP tap-rooted and drought tolerant, mining moisture from lower soil layers. Hence A is true but R is false." },
  { id:"gtl_018", qNo:18, subject:"rabi-crops", question:"Wilt of chickpea (Bengal gram), a major soil-borne disease, is caused by:", options:["Verticillium dahliae", "Fusarium oxysporum f.sp. ciceri", "Rhizoctonia bataticola", "Sclerotium rolfsii"], correct:1, explanation:"Chickpea wilt is caused by the soil- and seed-borne fungus Fusarium oxysporum f.sp. ciceri. Infected plants show drooping, yellowing and internal vascular browning; management uses resistant varieties, seed treatment and crop rotation." },
  { id:"gtl_019", qNo:19, subject:"rabi-crops", question:"In sunflower, supplementary hand pollination or use of bee colonies is recommended because the crop is:", options:["Wind-pollinated and fully self-compatible", "Strictly self-pollinated and cleistogamous", "Apomictic, setting seed without any pollination", "Largely cross-pollinated and self-incompatible"], correct:3, explanation:"Sunflower is largely cross-pollinated and shows self-incompatibility, so reliable seed set depends on insect (especially honeybee) pollination. Placing bee colonies in the field or doing supplementary hand pollination markedly improves seed set and yield." },

  // ── GENETICS & PLANT BREEDING (7) ──
  { id:"gtl_020", qNo:20, subject:"genetics", question:"The term 'heterosis' (hybrid vigour) was coined by:", options:["G.H. Shull", "G. Mendel", "T.H. Morgan", "N.I. Vavilov"], correct:0, explanation:"George Harrison Shull coined the term 'heterosis' in 1914 to describe the superiority of an F1 hybrid over its parents. His work on inbreeding and crossing in maize laid the foundation of modern hybrid breeding." },
  { id:"gtl_021", qNo:21, subject:"genetics", question:"Assertion (A): Selection is ineffective within a pure line.\nReason (R): A pure line is the progeny of a single self-pollinated homozygous plant, so individuals within it are genetically identical and variation among them is purely environmental.", options:["A is true, but R is false", "Both A and R are true, but R does not explain A", "A is false, but R is true", "Both A and R are true, and R explains A"], correct:3, explanation:"Both true and R explains A. Johannsen's pure-line theory states that a pure line is genetically uniform (descended from one homozygous self-fertilised plant). Since all genetic variation has been fixed, any differences among plants of a pure line are due to environment alone, and selection within it produces no genetic gain." },
  { id:"gtl_022", qNo:22, subject:"genetics", question:"Match the three columns — Scientist, their major contribution, and the organism/material used:", matchTable:{ headers:["Column-I (Scientist)", "Column-II (Contribution)", "Column-III (Organism/Material)"], rows:[ ["A. Johannsen", "1. Heterosis (hybrid vigour) concept", "i. Maize"], ["B. Shull", "2. Semi-dwarf high-yielding wheat", "ii. Barley"], ["C. Stadler", "3. Pure line theory", "iii. Beans"], ["D. Borlaug", "4. X-ray induced mutations", "iv. Wheat"] ] }, options:["A-1-i, B-3-iii, C-4-ii, D-2-iv", "A-3-iii, B-1-i, C-4-ii, D-2-iv", "A-3-iii, B-1-i, C-2-iv, D-4-ii", "A-4-ii, B-1-i, C-3-iii, D-2-iv"], correct:1, explanation:"Johannsen gave the pure line theory working with beans (3-iii); Shull described heterosis in maize (1-i); Stadler first demonstrated X-ray induced mutations in barley (4-ii); Borlaug developed semi-dwarf high-yielding wheat (2-iv). Hence A-3-iii, B-1-i, C-4-ii, D-2-iv." },
  { id:"gtl_023", qNo:23, subject:"genetics", question:"In molecular plant breeding, selecting plants using DNA markers that are tightly linked to a desired gene is called:", options:["Mass selection", "Pure line selection", "Clonal selection", "Marker-Assisted Selection (MAS)"], correct:3, explanation:"Marker-Assisted Selection (MAS) uses DNA markers tightly linked to a target gene/trait to identify and select desirable plants in the laboratory - often at the seedling stage, without waiting to observe the phenotype - making breeding faster and more precise." },
  { id:"gtl_024", qNo:24, subject:"genetics", question:"Match List-I (Breeding term) with List-II (Meaning) and select the correct combination:", matchTable:{ headers:["List-I (Breeding term)", "List-II (Meaning)"], rows:[["A. Emasculation", "1. Crossing F1 with one of its parents"], ["B. Backcross", "2. Removal of anthers from the female parent before pollen shed"], ["C. Apomixis", "3. Transfer of one or few genes from one species into another through repeated crossing"], ["D. Introgression", "4. Seed formation without fertilisation (asexual seed)"]] }, options:["A-2, B-4, C-1, D-3", "A-2, B-1, C-3, D-4", "A-2, B-1, C-4, D-3", "A-1, B-2, C-4, D-3"], correct:2, explanation:"Emasculation = removing anthers from the female parent (2); Backcross = crossing F1 back to a parent (1); Apomixis = asexual seed formation without fertilisation (4); Introgression = transfer of a few genes across species via repeated crossing/backcrossing (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_025", qNo:25, subject:"genetics", question:"Cytoplasmic Male Sterility (CMS) is widely exploited in hybrid seed production because it:", options:["Increases the pollen fertility of the female line", "Eliminates the need for manual emasculation of the female parent", "Makes the hybrid seed genetically uniform without a restorer", "Converts a cross-pollinated crop into a self-pollinated one"], correct:1, explanation:"CMS provides a genetic mechanism of male sterility (controlled by the cytoplasm/mitochondria), so the female (seed) parent produces no functional pollen. This removes the costly, labour-intensive step of manual emasculation in hybrid seed production. A fertility-restorer (Rf) line is then used to restore fertility in the commercial hybrid where seed/grain is the product." },
  { id:"gtl_026", qNo:26, subject:"genetics", question:"Consider the following statements on mutation:\n1. The spontaneous mutation rate is about one in a million (10 to the power -6) per gene per generation.\n2. EMS (ethyl methane sulphonate) is a chemical mutagen.\n3. L.J. Stadler first demonstrated X-ray induced mutations in fruit fly (Drosophila).\nWhich of the statements are correct?", options:["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], correct:0, explanation:"Statements 1 and 2 are correct: spontaneous mutation rate is about 10 to the power -6 per gene per generation, and EMS is a classic alkylating chemical mutagen. Statement 3 is FALSE — Stadler demonstrated X-ray mutations in BARLEY and MAIZE; it was H.J. Muller who demonstrated X-ray induced mutations in Drosophila." },

  // ── SEED TECHNOLOGY (4) ──
  { id:"gtl_027", qNo:27, subject:"seed-technology", question:"In the seed multiplication chain, the correct descending order of seed classes is:", options:["Nucleus - Breeder - Foundation - Certified", "Certified - Foundation - Breeder - Nucleus", "Breeder - Certified - Foundation - Nucleus", "Foundation - Nucleus - Breeder - Certified"], correct:0, explanation:"The seed chain proceeds Nucleus seed - Breeder seed - Foundation seed - Certified seed. Each stage is multiplied from the previous one under decreasing genetic control, with Nucleus seed being the genetically purest and Certified seed reaching the farmer." },
  { id:"gtl_028", qNo:28, subject:"seed-technology", question:"Match List-I (Seed class) with List-II (certificate / tag colour) and select the correct combination:", matchTable:{ headers:["List-I (Seed class)", "List-II (Tag / certificate colour)"], rows:[["A. Breeder seed", "1. White"], ["B. Foundation seed", "2. Azure blue"], ["C. Certified seed", "3. Golden yellow"]] }, options:["A-1, B-2, C-3", "A-2, B-1, C-3", "A-3, B-2, C-1", "A-3, B-1, C-2"], correct:3, explanation:"As per the DA-111 notes: Breeder seed carries a Golden-yellow certificate; Foundation seed a White certificate (minimum genetic purity 99.5%); Certified seed an Azure-blue certificate (minimum genetic purity 99%). Hence A-3, B-1, C-2." },
  { id:"gtl_029", qNo:29, subject:"seed-technology", question:"Assertion (A): Hard-seededness in many legumes is a form of seed dormancy.\nReason (R): The seed coat is impermeable to water and gases, preventing imbibition and germination until it is broken or weathered.", options:["Both A and R are true, but R does not explain A", "A is false, but R is true", "Both A and R are true, and R explains A", "A is true, but R is false"], correct:2, explanation:"Both true and R explains A. Hard-seededness (physical/seed-coat dormancy) is common in legumes; the hard, waxy, impermeable seed coat blocks entry of water and oxygen, so the seed cannot imbibe and germinate until the coat is scarified, weathered or otherwise broken. R is thus the correct cause of A." },
  { id:"gtl_030", qNo:30, subject:"seed-technology", question:"The 'Father of Seed Testing', who established the first seed testing station at Tharandt (Germany) in 1869, is:", options:["Norman Borlaug", "Friedrich Nobbe", "Wilhelm Johannsen", "Emil Truog"], correct:1, explanation:"Friedrich Nobbe established the world's first seed testing station at Tharandt, Germany, in 1869 and authored the first handbook of seed testing ('Handbuch der Samenkunde'); he is regarded as the Father of Seed Testing." },

  // ── SOIL SCIENCE (6) ──
  { id:"gtl_031", qNo:31, subject:"soil-science", question:"Among silicate clay minerals, the highest cation exchange capacity (CEC) and shrink-swell behaviour are shown by:", options:["Kaolinite (1:1 type)", "Illite (2:1 non-expanding)", "Montmorillonite (2:1 type)", "Halloysite"], correct:2, explanation:"Montmorillonite is a 2:1 expanding (smectite) clay with very high specific surface area and isomorphous substitution, giving it the highest CEC (about 80-150 cmol(p+)/kg) and strong shrink-swell behaviour. Kaolinite (1:1) has the lowest CEC; illite is intermediate and non-expanding." },
  { id:"gtl_032", qNo:32, subject:"soil-science", question:"Assertion (A): Soils high in clay and humus generally have a high cation exchange capacity.\nReason (R): Clay and humus are the smallest, colloidal-sized fractions of the soil.", options:["Both A and R are true, but R does not explain A", "Both A and R are true, and R explains A", "A is true, but R is false", "A is false, but R is true"], correct:0, explanation:"Both statements are true, but R is not the correct explanation. A high CEC is due to the abundant NEGATIVE CHARGES on clay and humus colloids that hold exchangeable cations - not merely because they are the smallest particles. Small size accompanies, but does not cause, the charge. Hence R does not explain A." },
  { id:"gtl_033", qNo:33, subject:"soil-science", question:"Match the three columns — Soil order, its diagnostic feature, and a common example:", matchTable:{ headers:["Column-I (Soil order)", "Column-II (Diagnostic feature)", "Column-III (Example)"], rows:[ ["A. Vertisols", "1. Deep shrink-swell cracking clay", "i. Desert soils"], ["B. Aridisols", "2. Organic (peat) soils", "ii. Black cotton soils"], ["C. Histosols", "3. Dry; salt/carbonate accumulation", "iii. Prairie/grassland soils"], ["D. Mollisols", "4. Thick, dark, fertile (mollic) surface", "iv. Peat/marsh soils"] ] }, options:["A-3-i, B-1-ii, C-2-iv, D-4-iii", "A-1-ii, B-3-i, C-2-iv, D-4-iii", "A-1-ii, B-2-i, C-3-iv, D-4-iii", "A-1-iii, B-3-i, C-2-iv, D-4-ii"], correct:1, explanation:"Vertisols = deep shrink-swell cracking clays = black cotton soils (1-ii); Aridisols = dry soils with salt/carbonate accumulation = desert soils (3-i); Histosols = organic peat soils = peat/marsh soils (2-iv); Mollisols = thick dark mollic surface = prairie/grassland soils (4-iii). Hence A-1-ii, B-3-i, C-2-iv, D-4-iii." },
  { id:"gtl_034", qNo:34, subject:"soil-science", question:"The element chiefly responsible for soil acidity (low pH) in highly weathered soils is predominantly:", options:["Exchangeable sodium and soluble carbonate", "Free calcium carbonate (lime) in the soil", "Exchangeable aluminium (along with exchangeable hydrogen)", "Soluble nitrate and chloride salts"], correct:2, explanation:"In strongly acid soils much of the acidity comes from exchangeable aluminium ions (Al3+), which hydrolyse in water to release H+ and lower pH, together with exchangeable H+. Liming neutralises this acidity; sodium/carbonate and free lime are linked to alkaline/sodic conditions instead." },
  { id:"gtl_035", qNo:35, subject:"soil-science", question:"Match List-I (soil-forming factor, after Jenny) with List-II (its role) and select the correct combination:", matchTable:{ headers:["List-I (Factor)", "List-II (Role in soil formation)"], rows:[["A. Parent material", "1. Rainfall and temperature that drive weathering"], ["B. Climate", "2. The weathered rock / material from which soil develops"], ["C. Organisms", "3. Slope / relief affecting drainage and erosion"], ["D. Relief (topography)", "4. Vegetation, microbes and fauna adding organic matter"]] }, options:["A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3"], correct:3, explanation:"Per Jenny (1941), soil forms from climate and organisms acting on parent material as conditioned by relief over time. Parent material = the weathered rock soil develops from (2); Climate = rainfall/temperature driving weathering (1); Organisms = vegetation, microbes and fauna adding organic matter (4); Relief = slope affecting drainage and erosion (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_036", qNo:36, subject:"soil-science", question:"According to the USDA textural classification, a soil that is generally considered ideal for most crops because it holds adequate water yet drains and aerates well is:", options:["Loam", "Sandy soil", "Clay soil", "Silt"], correct:0, explanation:"Loam — a balanced mixture of sand, silt and clay — is regarded as the ideal agricultural texture. It retains sufficient moisture and nutrients (from clay and silt) while still draining and aerating well (from sand), giving good workability and root growth." },

  // ── SOIL FERTILITY / MANURES (5) ──
  { id:"gtl_037", qNo:37, subject:"soil-fertility", question:"The nitrogenous fertiliser with the highest nitrogen content among the following is:", options:["Ammonium sulphate", "Urea", "Calcium ammonium nitrate (CAN)", "Ammonium chloride"], correct:1, explanation:"Urea contains about 46% N — the highest among common solid nitrogenous fertilisers. Ammonium sulphate has about 20.6% N, CAN about 25% N, and ammonium chloride about 26% N. Urea's high analysis lowers transport and handling cost per unit N." },
  { id:"gtl_038", qNo:38, subject:"soil-fertility", question:"Match List-I (Fertiliser) with List-II (Approximate nutrient content) and select the correct combination:", matchTable:{ headers:["List-I (Fertiliser)", "List-II (Approximate nutrient content)"], rows:[["A. Urea", "1. 18% N, 46% P2O5"], ["B. DAP", "2. 60% K2O"], ["C. Muriate of Potash (MOP)", "3. 16% P2O5 (with S and Ca)"], ["D. Single Super Phosphate (SSP)", "4. 46% N"]] }, options:["A-1, B-4, C-2, D-3", "A-4, B-1, C-3, D-2", "A-4, B-2, C-1, D-3", "A-4, B-1, C-2, D-3"], correct:3, explanation:"Urea = 46% N (4); DAP = 18% N + 46% P2O5 (1); MOP = 60% K2O (2); SSP = 16% P2O5 plus sulphur and calcium (3). Hence A-4, B-1, C-2, D-3." },
  { id:"gtl_039", qNo:39, subject:"soil-fertility", question:"Assertion (A): Surface broadcasting of urea on a wet soil or standing water can cause large nitrogen losses.\nReason (R): Urea is hydrolysed by the enzyme urease to ammonium carbonate, and the ammonia so formed is lost to the atmosphere by volatilisation.", options:["A is false, but R is true", "Both A and R are true, but R does not explain A", "Both A and R are true, and R explains A", "A is true, but R is false"], correct:2, explanation:"Both true and R explains A. Soil urease rapidly hydrolyses urea to ammonium carbonate; on alkaline or wet surfaces this converts to ammonia gas (NH3) which volatilises and is lost. This is exactly why surface-applied urea should be incorporated into the soil or applied before irrigation to cut losses." },
  { id:"gtl_040", qNo:40, subject:"soil-fertility", question:"Consider the following statements about biofertilisers:\n1. Rhizobium fixes atmospheric nitrogen in symbiotic association with legume roots.\n2. Azospirillum is a free-living/associative nitrogen fixer used for cereals.\n3. Phosphobacteria (PSB) fix atmospheric nitrogen directly.\nWhich of the statements are correct?", options:["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2 and 3"], correct:0, explanation:"Statements 1 and 2 are correct: Rhizobium is a symbiotic N-fixer of legumes; Azospirillum is an associative N-fixer recommended for cereals/grasses. Statement 3 is FALSE — Phosphate Solubilising Bacteria (PSB) do NOT fix nitrogen; they solubilise insoluble soil phosphates into plant-available forms." },
  { id:"gtl_041", qNo:41, subject:"soil-fertility", question:"'Khaira' disease of rice, characterised by bronzing of leaves, is caused by the deficiency of:", options:["Iron", "Zinc", "Boron", "Manganese"], correct:1, explanation:"Khaira disease of rice is caused by zinc (Zn) deficiency, showing as brown spots and bronzing of lower leaves, stunting and delayed tillering, especially in calcareous and submerged soils. It is corrected by soil/foliar application of zinc sulphate." },

  // ── ENTOMOLOGY (6) ──
  { id:"gtl_042", qNo:42, subject:"entomology", question:"Which of the following is a defining characteristic of class Insecta that separates them from other arthropods?", options:["Cephalothorax with five pairs of legs", "Four pairs of legs and two body regions", "Three pairs of legs and three body regions (head, thorax, abdomen)", "Numerous body segments each bearing a pair of legs"], correct:2, explanation:"Insects have THREE pairs of legs (hexapod) and the body divided into THREE regions — head, thorax and abdomen — usually with one pair of antennae and (often) two pairs of wings. Four pairs of legs with two body regions is Arachnida; many legs per segment characterise Myriapoda." },
  { id:"gtl_043", qNo:43, subject:"entomology", question:"Match List-I (Insect order) with List-II (Diagnostic character) and select the correct combination:", matchTable:{ headers:["List-I (Insect order)", "List-II (Diagnostic character)"], rows:[["A. Coleoptera", "1. Single pair of wings; hind wings reduced to halteres"], ["B. Hemiptera", "2. Fore wings hardened into elytra"], ["C. Lepidoptera", "3. Piercing and sucking mouthparts; fore wings often hemelytra"], ["D. Diptera", "4. Wings covered with scales; siphoning proboscis"]] }, options:["A-2, B-3, C-1, D-4", "A-2, B-4, C-3, D-1", "A-3, B-2, C-4, D-1", "A-2, B-3, C-4, D-1"], correct:3, explanation:"Coleoptera (beetles) = fore wings hardened into elytra (2); Hemiptera (true bugs) = piercing-sucking mouthparts with hemelytra (3); Lepidoptera (moths/butterflies) = scaly wings and siphoning proboscis (4); Diptera (flies) = single pair of wings with halteres (1). Hence A-2, B-3, C-4, D-1." },
  { id:"gtl_044", qNo:44, subject:"entomology", question:"Assertion (A): A butterfly shows complete metamorphosis (holometaboly).\nReason (R): In the butterfly the larva closely resembles the adult and there is no pupal stage in the life cycle.", options:["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, but R is false", "A is false, but R is true"], correct:2, explanation:"A is TRUE - the butterfly has complete metamorphosis (egg, larva, pupa, adult). R is FALSE - in complete metamorphosis the larva (caterpillar) is markedly DIFFERENT from the adult and there IS a distinct pupal stage. Hence A is true but R is false." },
  { id:"gtl_045", qNo:45, subject:"entomology", question:"Match the three columns — Insect, its order, and its mouthpart type:", matchTable:{ headers:["Column-I (Insect)", "Column-II (Order)", "Column-III (Mouthpart)"], rows:[ ["A. Honeybee", "1. Orthoptera", "i. Chewing and lapping"], ["B. Housefly", "2. Hymenoptera", "ii. Sponging"], ["C. Grasshopper", "3. Lepidoptera", "iii. Biting and chewing"], ["D. Butterfly", "4. Diptera", "iv. Siphoning"] ] }, options:["A-1-iii, B-4-ii, C-2-i, D-3-iv", "A-2-i, B-4-ii, C-1-iii, D-3-iv", "A-2-i, B-4-iii, C-1-ii, D-3-iv", "A-2-ii, B-4-i, C-1-iii, D-3-iv"], correct:1, explanation:"Honeybee = Hymenoptera, chewing-and-lapping mouthparts (2-i); Housefly = Diptera, sponging (4-ii); Grasshopper = Orthoptera, biting-and-chewing (1-iii); Butterfly = Lepidoptera, siphoning (3-iv). Hence A-2-i, B-4-ii, C-1-iii, D-3-iv." },
  { id:"gtl_046", qNo:46, subject:"entomology", question:"Organophosphate and carbamate insecticides kill insects mainly by:", options:["Inhibiting the enzyme acetylcholinesterase at nerve synapses", "Blocking sodium channels in nerve axons", "Acting as agonists of the nicotinic acetylcholine receptor", "Disrupting the moulting hormone (ecdysone)"], correct:0, explanation:"Organophosphates and carbamates inhibit acetylcholinesterase, the enzyme that breaks down the neurotransmitter acetylcholine. Acetylcholine then accumulates at synapses, causing continuous nerve firing, paralysis and death. (Pyrethroids act on sodium channels; neonicotinoids are nicotinic-receptor agonists.)" },
  { id:"gtl_047", qNo:47, subject:"entomology", question:"Trichogramma, mass-released for biological control of borer pests, is a/an:", options:["Larval predator", "Adult predator", "Pupal parasitoid", "Egg parasitoid"], correct:3, explanation:"Trichogramma spp. are minute hymenopteran wasps that are EGG parasitoids — they lay their eggs inside the eggs of lepidopteran borers (such as stem borers and bollworms), killing the host before the damaging larva can hatch. They are released as Trichocards in the field." },

  // ── CROP PESTS (4) ──
  { id:"gtl_048", qNo:48, subject:"crop-pests", question:"In rice, the symptom 'dead heart' at the vegetative stage and 'white ear head' at the reproductive stage is caused by:", options:["Brown plant hopper (Nilaparvata lugens)", "Rice gall midge (Orseolia oryzae)", "Yellow stem borer (Scirpophaga incertulas)", "Rice hispa (Dicladispa armigera)"], correct:2, explanation:"The rice yellow stem borer (Scirpophaga incertulas) bores into the tiller. At the vegetative stage the central shoot dries to give a 'dead heart', and at the panicle stage it produces empty, whitish, unfilled panicles called 'white ear head'. Both symptoms are diagnostic of stem borer attack." },
  { id:"gtl_049", qNo:49, subject:"crop-pests", question:"Match List-I (Insect pest) with List-II (Host crop) and select the correct combination:", matchTable:{ headers:["List-I (Insect pest)", "List-II (Host crop)"], rows:[["A. Pink bollworm", "1. Sugarcane"], ["B. Pyrilla", "2. Cotton"], ["C. Pod borer (Helicoverpa armigera)", "3. Cole crops (cabbage/cauliflower)"], ["D. Diamond back moth", "4. Redgram/chickpea"]] }, options:["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3"], correct:0, explanation:"Pink bollworm is a key pest of cotton (2); Pyrilla (sugarcane leafhopper) of sugarcane (1); Helicoverpa armigera (gram pod borer) of redgram/chickpea and many crops (4); Diamond back moth of cole crops like cabbage and cauliflower (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_050", qNo:50, subject:"crop-pests", question:"Consider the following statements about pest management thresholds:\n1. Economic Threshold Level (ETL) is the pest density at which control measures should be initiated to prevent the population reaching the EIL.\n2. Economic Injury Level (EIL) is the lowest pest density that will cause economic damage.\n3. ETL is always higher than the EIL.\nWhich of the statements are correct?", options:["1, 2 and 3", "2 and 3 only", "1 and 3 only", "1 and 2 only"], correct:3, explanation:"Statements 1 and 2 are correct by definition. Statement 3 is FALSE — the ETL is set BELOW (lower than) the EIL so that control action begins in time to stop the population from reaching the economic injury level; it is therefore lower, not higher, than the EIL." },
  { id:"gtl_051", qNo:51, subject:"crop-pests", question:"The pulse beetle (Callosobruchus chinensis), a serious storage pest, damages grain at which stage?", options:["Only in the standing field crop", "Grubs feed inside stored seeds, hollowing them out", "Only the adults bite the seed surface", "It feeds only on the seed coat without affecting the kernel"], correct:1, explanation:"In the pulse beetle, the female lays eggs on the seed; the emerging grub bores INTO the stored pulse and feeds inside, hollowing out the cotyledons before pupating within. Infestation often begins in the field but the major, characteristic damage occurs to stored seeds, drastically reducing germination and weight." },

  // ── PLANT PATHOLOGY (7) ──
  { id:"gtl_052", qNo:52, subject:"plant-pathology", question:"Bordeaux mixture, the first widely used fungicide, is a combination of:", options:["Zinc sulphate and lime", "Sulphur and lime", "Mercuric chloride and water", "Copper sulphate and quick/slaked lime"], correct:3, explanation:"Bordeaux mixture is prepared from copper sulphate and lime (quick or slaked lime) in water. Discovered by P.M.A. Millardet in France (1885) to control downy mildew of grapes, it is a classic protectant (contact) fungicide effective against many fungal and bacterial diseases." },
  { id:"gtl_053", qNo:53, subject:"plant-pathology", question:"Assertion (A): Downy mildews are favoured by cool, humid (wet) weather, whereas powdery mildews can develop even under relatively dry conditions.\nReason (R): Downy mildew fungi (Oomycetes) require free surface moisture for zoospore germination, while powdery mildew conidia can germinate at high humidity without a film of water.", options:["A is false, but R is true", "Both A and R are true, and R explains A", "A is true, but R is false", "Both A and R are true, but R does not explain A"], correct:1, explanation:"Both true and R explains A. Downy mildews (Oomycetes) produce motile zoospores that need a film of free water on the surface, so they spread in cool, wet weather. Powdery mildew conidia, however, can germinate at high relative humidity even without free water and tolerate drier conditions — exactly the difference R describes, making it the correct explanation of A." },
  { id:"gtl_054", qNo:54, subject:"plant-pathology", question:"Match List-I (Disease) with List-II (Causal organism) and select the correct combination:", matchTable:{ headers:["List-I (Disease)", "List-II (Causal organism)"], rows:[["A. Citrus canker", "1. Phytophthora infestans"], ["B. Late blight of potato", "2. Xanthomonas axonopodis pv. citri"], ["C. Red rot of sugarcane", "3. Cercospora spp."], ["D. Tikka of groundnut", "4. Colletotrichum falcatum"]] }, options:["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3"], correct:0, explanation:"Citrus canker = Xanthomonas axonopodis pv. citri, a bacterium (2); Late blight of potato = Phytophthora infestans, an oomycete (1); Red rot of sugarcane = Colletotrichum falcatum, a fungus (4); Tikka (leaf spot) of groundnut = Cercospora spp. (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_055", qNo:55, subject:"plant-pathology", question:"Match the three columns — Disease, its pathogen, and the pathogen type:", matchTable:{ headers:["Column-I (Disease)", "Column-II (Pathogen)", "Column-III (Pathogen type)"], rows:[ ["A. Late blight of potato", "1. Cercospora", "i. Bacterium"], ["B. Citrus canker", "2. Phytophthora infestans", "ii. Fungus (Oomycete)"], ["C. Tikka of groundnut", "3. Begomovirus", "iii. Fungus"], ["D. Bunchy top of banana", "4. Xanthomonas", "iv. Virus"] ] }, options:["A-2-ii, B-1-i, C-4-iii, D-3-iv", "A-2-iii, B-4-i, C-1-ii, D-3-iv", "A-1-ii, B-4-i, C-2-iii, D-3-iv", "A-2-ii, B-4-i, C-1-iii, D-3-iv"], correct:3, explanation:"Late blight = Phytophthora infestans, an Oomycete fungus (2-ii); Citrus canker = Xanthomonas, a bacterium (4-i); Tikka of groundnut = Cercospora, a true fungus (1-iii); Bunchy top of banana = a Begomovirus (3-iv). Hence A-2-ii, B-4-i, C-1-iii, D-3-iv." },
  { id:"gtl_056", qNo:56, subject:"plant-pathology", question:"Which of the following is a SYSTEMIC fungicide (absorbed and translocated within the plant)?", options:["Carbendazim", "Copper oxychloride", "Mancozeb", "Sulphur"], correct:0, explanation:"Carbendazim (a benzimidazole) is a systemic fungicide — it is absorbed by the plant and moves within the tissues, giving curative as well as protective action. Mancozeb, copper oxychloride and sulphur are contact (protectant) fungicides that remain on the plant surface." },
  { id:"gtl_057", qNo:57, subject:"plant-pathology", question:"Consider the following statements:\n1. Viruses are obligate parasites consisting of nucleic acid surrounded by a protein coat.\n2. Phytoplasmas are wall-less prokaryotes that live in the phloem and are transmitted by leafhoppers.\n3. Phytoplasmas can be easily grown on ordinary nutrient media in the laboratory.\nWhich of the statements are correct?", options:["1 and 3 only", "2 and 3 only", "1 and 2 only", "1, 2 and 3"], correct:2, explanation:"Statements 1 and 2 are correct. Viruses are obligate parasites (nucleic acid + protein coat) and phytoplasmas are wall-less, phloem-limited prokaryotes spread by leafhoppers. Statement 3 is FALSE — phytoplasmas are obligate parasites that have NOT been cultured on ordinary artificial media." },
  { id:"gtl_058", qNo:58, subject:"plant-pathology", question:"Assertion (A): Late blight of potato is the classic example of an epidemic plant disease.\nReason (R): An epidemic disease occurs widely but periodically in a destructive form, as in the Irish Famine of 1845.", options:["Both A and R are true, but R does not explain A", "Both A and R are true, and R explains A", "A is true, but R is false", "A is false, but R is true"], correct:1, explanation:"Both are true and R explains A. The DA-171 notes define an epidemic disease as one that 'occurs widely but periodically in a destructive form', citing late blight of potato and the Irish Famine of 1845 as the example. R gives exactly the definition that makes A true." },

  // ── FARM MACHINERY (5) ──
  { id:"gtl_059", qNo:59, subject:"farm-machinery", question:"The mould-board plough is correctly classified as a:", options:["Combined seed-cum-fertiliser drilling implement", "Secondary tillage implement for fine seedbed preparation", "Inter-cultivation implement used for weeding between rows", "Primary tillage implement that inverts the furrow slice"], correct:3, explanation:"The mould-board plough is a primary tillage implement: it cuts, lifts and inverts the furrow slice, burying weeds and residues and exposing fresh soil. Secondary tillage implements (harrows, cultivators) follow to prepare a fine seedbed." },
  { id:"gtl_060", qNo:60, subject:"farm-machinery", question:"Match List-I (Implement) with List-II (Function) and select the correct combination:", matchTable:{ headers:["List-I (Implement)", "List-II (Function)"], rows:[["A. Cultivator", "1. Places seed at the proper depth and spacing"], ["B. Disc harrow", "2. Secondary tillage; breaks clods and cuts residue"], ["C. Seed drill", "3. Inter-cultivation / secondary tillage and weed control"], ["D. Rotavator", "4. Pulverises soil and prepares seedbed in a single pass using rotating blades"]] }, options:["A-3, B-2, C-1, D-4", "A-2, B-3, C-1, D-4", "A-3, B-2, C-4, D-1", "A-1, B-2, C-3, D-4"], correct:0, explanation:"Cultivator = inter-cultivation/secondary tillage and weed control (3); Disc harrow = secondary tillage, breaks clods and cuts residue (2); Seed drill = places seed at correct depth and spacing (1); Rotavator = pulverises and prepares seedbed in one pass with rotating blades (4). Hence A-3, B-2, C-1, D-4." },
  { id:"gtl_061", qNo:61, subject:"farm-machinery", question:"Assertion (A): The rotational speed of a tractor PTO (Power Take-Off) shaft is internationally standardised.\nReason (R): The PTO shaft transmits power from the tractor engine to operate trailed and mounted implements.", options:["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, but R is false", "A is false, but R is true"], correct:1, explanation:"Both statements are true, but R is not the correct explanation. PTO speed is standardised (540 and 1000 rpm) SO THAT implements from different manufacturers can be matched to any tractor - that is the reason for the standard. R only states what a PTO does, which does not explain WHY its speed is standardised. Hence R does not explain A." },
  { id:"gtl_062", qNo:62, subject:"farm-machinery", question:"For applying systemic insecticides as a fine, uniform spray on a field crop, the most suitable nozzle is the:", options:["Flooding (deflector) nozzle", "Off-centre nozzle", "Hollow cone nozzle", "Solid stream nozzle"], correct:2, explanation:"The hollow cone nozzle produces fine droplets in a cone pattern, giving good coverage and penetration of foliage — ideal for insecticides and fungicides where thorough leaf coverage is needed. Flat-fan/flooding nozzles are preferred for herbicide application; solid stream nozzles deliver a jet for spot/directed spraying." },
  { id:"gtl_063", qNo:63, subject:"farm-machinery", question:"Assertion (A): In a four-stroke engine the camshaft rotates at half the speed of the crankshaft.\nReason (R): The cycle is completed in two revolutions of the crankshaft, so each valve need open only once in that period.", options:["A is false, but R is true", "Both A and R are true, but R does not explain A", "A is true, but R is false", "Both A and R are true, and R explains A"], correct:3, explanation:"Both are true and R explains A. The DA-151 notes state the camshaft runs at exactly half the crankshaft speed in a four-stroke engine. Because one complete cycle (suction, compression, power, exhaust) takes two crankshaft revolutions, each valve opens once per two revolutions - which is why the camshaft turns at half speed." },

  // ── SURVEYING (4) ──
  { id:"gtl_064", qNo:64, subject:"surveying", question:"The operation of fixing intermediate points on a straight survey line between its end stations is called:", options:["Offsetting", "Levelling", "Ranging", "Traversing"], correct:2, explanation:"Ranging is the process of establishing intermediate points along a straight line between two end stations so that the chaining is done along a truly straight line. It is done with ranging rods (direct ranging when stations are intervisible)." },
  { id:"gtl_065", qNo:65, subject:"surveying", question:"Match List-I (Survey instrument) with List-II (Use) and select the correct combination:", matchTable:{ headers:["List-I (Survey instrument)", "List-II (Use)"], rows:[["A. Prismatic compass", "1. Direct plotting of the map in the field"], ["B. Plane table", "2. Measuring magnetic bearings of lines"], ["C. Dumpy level", "3. Setting out right angles (perpendicular offsets)"], ["D. Cross staff", "4. Determining differences in elevation (levelling)"]] }, options:["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-2, B-4, C-1, D-3"], correct:0, explanation:"Prismatic compass = measuring magnetic bearings (2); Plane table = direct plotting of the map in the field (1); Dumpy level = levelling / difference in elevation (4); Cross staff = setting out right angles for offsets (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_066", qNo:66, subject:"surveying", question:"Match the three columns — Chain, its length, and its typical use:", matchTable:{ headers:["Column-I (Chain)", "Column-II (Length)", "Column-III (Typical use)"], rows:[ ["A. Gunter's chain", "1. 100 ft", "i. Cadastral / revenue field measurement"], ["B. Engineer's chain", "2. 20/30 m", "ii. Engineering surveys"], ["C. Revenue chain", "3. 66 ft", "iii. Area in acres & furlongs"], ["D. Metric chain", "4. 33 ft", "iv. General metric surveys"] ] }, options:["A-3-ii, B-1-iii, C-4-i, D-2-iv", "A-3-iii, B-1-ii, C-4-i, D-2-iv", "A-1-iii, B-3-ii, C-4-i, D-2-iv", "A-3-iii, B-1-ii, C-2-i, D-4-iv"], correct:1, explanation:"Gunter's chain = 66 ft, used for area in acres/furlongs (3-iii); Engineer's chain = 100 ft, for engineering surveys (1-ii); Revenue chain = 33 ft, for cadastral/revenue field measurement (4-i); Metric chain = 20/30 m, for general metric surveys (2-iv). Hence A-3-iii, B-1-ii, C-4-i, D-2-iv." },
  { id:"gtl_067", qNo:67, subject:"surveying", question:"Assertion (A): A contour line on a map joins points of equal elevation.\nReason (R): Two different contour lines normally cross each other on level ground.", options:["Both A and R are true, but R does not explain A", "Both A and R are true, and R explains A", "A is false, but R is true", "A is true, but R is false"], correct:3, explanation:"A is true (a contour joins points of equal elevation), but R is FALSE. Contour lines never cross one another (except in the special case of an overhanging cliff), because a single point cannot have two different elevations. Hence A is true but R is false." },

  // ── AGRICULTURAL ECONOMICS (6) ──
  { id:"gtl_068", qNo:68, subject:"agricultural-economics", question:"The price elasticity of demand for staple food grains is generally:", options:["Greater than one (elastic)", "Less than one (inelastic)", "Exactly equal to one (unitary)", "Infinite (perfectly elastic)"], correct:1, explanation:"Demand for staple food grains is price-inelastic (elasticity < 1) because they are necessities — the quantity demanded changes proportionately less than the change in price. This is why a bumper harvest can sharply depress prices and farm incomes." },
  { id:"gtl_069", qNo:69, subject:"agricultural-economics", question:"Assertion (A): As a household's income rises, the proportion of its income spent on food tends to rise.\nReason (R): Engel's Law states that the income elasticity of demand for food is less than one.", options:["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is false, but R is true", "A is true, but R is false"], correct:2, explanation:"A is FALSE - by Engel's Law the PROPORTION of income spent on food FALLS (not rises) as income increases, even though absolute spending may go up. R is TRUE - the income elasticity of demand for food is less than one (food is a necessity). Hence A is false but R is true." },
  { id:"gtl_070", qNo:70, subject:"agricultural-economics", question:"Match List-I (Economist) with List-II (Concept/Contribution) and select the correct combination:", matchTable:{ headers:["List-I (Economist)", "List-II (Concept/Contribution)"], rows:[["A. David Ricardo", "1. Theory of population growth vs food supply"], ["B. T.R. Malthus", "2. Law of comparative advantage"], ["C. Ernst Engel", "3. Economics of imperfect competition (MR-AR-elasticity relationship)"], ["D. Joan Robinson", "4. Income-food expenditure relationship (Engel's Law)"]] }, options:["A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-2, B-1, C-4, D-3", "A-2, B-4, C-1, D-3"], correct:2, explanation:"David Ricardo = Law of Comparative Advantage (2); T.R. Malthus = population vs food supply theory (1); Ernst Engel = income-food expenditure relationship / Engel's Law (4); Joan Robinson = Economics of Imperfect Competition and the MR-AR-elasticity relationship (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_071", qNo:71, subject:"agricultural-economics", question:"The Minimum Support Price (MSP) in India is recommended to the Government by the:", options:["Commission for Agricultural Costs and Prices (CACP)", "Reserve Bank of India (RBI), Mumbai", "Food Corporation of India (FCI), New Delhi", "National Bank for Agriculture and Rural Development"], correct:0, explanation:"The Commission for Agricultural Costs and Prices (CACP) recommends MSPs to the Government after considering the cost of production, demand-supply, price trends and terms of trade. The Cabinet Committee on Economic Affairs (CCEA) then announces the MSP." },
  { id:"gtl_072", qNo:72, subject:"agricultural-economics", question:"Consider the following statements about cooperatives in India:\n1. The first Cooperative Credit Societies Act was passed in 1904.\n2. Cooperatives follow the principle of 'one member, one vote'.\n3. Typically 50% of a cooperative's net profit is compulsorily kept as reserve fund.\nWhich of the statements are correct?", options:["2 and 3 only", "1 and 2 only", "1 and 3 only", "1, 2 and 3"], correct:1, explanation:"Statements 1 and 2 are correct: the Cooperative Credit Societies Act was passed in 1904, and cooperatives follow democratic 'one member, one vote' governance. Statement 3 is FALSE — it is customary to keep 25% (not 50%) of net profit as the reserve fund, with the remaining 75% available for distribution/other uses." },
  { id:"gtl_073", qNo:73, subject:"agricultural-economics", question:"In the law of variable proportions, a rational producer always operates in:", options:["Stage I (increasing returns)", "The boundary between Stage I and Stage III", "Stage III (negative returns)", "Stage II (diminishing returns)"], correct:3, explanation:"A rational producer operates in Stage II, the zone of diminishing (but still positive) returns, where both marginal and average products are falling yet positive (0 < MPP < APP) and total product is still rising. Stage I leaves resources under-utilised and Stage III has negative marginal product, so neither is rational." },

  // ── EXTENSION (6) ──
  { id:"gtl_074", qNo:74, subject:"extension", question:"A 'result demonstration' as an extension teaching method is classified under:", options:["Individual contact method", "Group contact method", "Mass contact method", "Audio-visual aid"], correct:1, explanation:"Result demonstration is a GROUP contact method — it shows a group of farmers the advantages of a recommended practice by comparing it with the local practice on a farmer's own field, proving the result with local evidence. (Method demonstrations and group meetings are also group methods.)" },
  { id:"gtl_075", qNo:75, subject:"extension", question:"Match List-I (Model/System) with List-II (Associated person) and select the correct combination:", matchTable:{ headers:["List-I (Model/System)", "List-II (Associated person)"], rows:[["A. Diffusion of innovations theory", "1. David Berlo"], ["B. Training & Visit (T&V) system", "2. Everett M. Rogers"], ["C. SMCR communication model", "3. Daniel Benor"], ["D. Adopter categories (innovativeness)", "4. Everett M. Rogers (adopter categories)"]] }, options:["A-2, B-3, C-1, D-4", "A-3, B-2, C-1, D-4", "A-2, B-1, C-3, D-4", "A-2, B-3, C-4, D-1"], correct:0, explanation:"Diffusion of innovations theory = Everett M. Rogers (2); Training & Visit (T&V) extension system = Daniel Benor of the World Bank (3); SMCR (Source-Message-Channel-Receiver) communication model = David Berlo (1); the adopter categories / innovativeness curve are also from Everett Rogers (4). Hence A-2, B-3, C-1, D-4." },
  { id:"gtl_076", qNo:76, subject:"extension", question:"Assertion (A): Result demonstration is an effective extension teaching method for introducing a new practice to farmers.\nReason (R): It lets farmers learn by seeing the result of the recommended practice at different stages on a field, which is convincing.", options:["A is false, but R is true", "Both A and R are true, but R does not explain A", "A is true, but R is false", "Both A and R are true, and R explains A"], correct:3, explanation:"Both are true and R explains A. The DA-291 notes list the advantages of result demonstrations as 'very useful to introduce new methods' and 'possibility of learning by seeing at different stages' - i.e. it convinces farmers by showing real results, which is exactly why it is effective." },
  { id:"gtl_077", qNo:77, subject:"extension", question:"Match the three columns — Extension programme, year of launch, and its main aim:", matchTable:{ headers:["Column-I (Programme)", "Column-II (Year)", "Column-III (Main aim)"], rows:[ ["A. IADP", "1. 1974", "i. Frontline demonstrations by scientists on cultivators' fields"], ["B. National Demonstration", "2. 1960", "ii. Intensive package of practices in selected districts"], ["C. First KVK", "3. 1998", "iii. Vocational training (farm science centre)"], ["D. ATMA", "4. 1964", "iv. Decentralised district-level extension reform"] ] }, options:["A-2-ii, B-4-i, C-1-iii, D-3-iv", "A-2-ii, B-1-i, C-4-iii, D-3-iv", "A-4-ii, B-2-i, C-1-iii, D-3-iv", "A-2-i, B-4-ii, C-1-iii, D-3-iv"], correct:0, explanation:"IADP (Intensive Agricultural District Programme) started in 1960 with an intensive package of practices in selected districts (2-ii); National Demonstration began in 1964 with frontline demonstrations by scientists on cultivators' fields (4-i); the first KVK (farm science centre) was set up in 1974 for vocational training (1-iii); ATMA was launched in 1998 as a decentralised district-level extension reform (3-iv). Hence A-2-ii, B-4-i, C-1-iii, D-3-iv." },
  { id:"gtl_078", qNo:78, subject:"extension", question:"The Training and Visit (T&V) system of agricultural extension was introduced in India with the support of:", options:["FAO", "The World Bank (Daniel Benor)", "USAID", "Ford Foundation"], correct:1, explanation:"The Training and Visit (T&V) system was conceived by Daniel Benor and introduced in India in the mid-1970s with World Bank support. It emphasised a single line of command, regular fortnightly training of village extension workers, and fixed visit schedules to contact farmers." },
  { id:"gtl_079", qNo:79, subject:"extension", question:"In David Berlo's SMCR model of communication, the letters S, M, C and R stand for:", options:["Sender, Method, Code, Reaction", "Source, Method, Channel, Response", "Source, Message, Channel, Receiver", "Sender, Message, Code, Receiver"], correct:2, explanation:"Berlo's SMCR model identifies the four key elements of communication as Source, Message, Channel and Receiver. Each element has factors (e.g., communication skills, attitudes, knowledge) that affect the fidelity of communication." },

  // ── HORTICULTURE (9) ──
  { id:"gtl_080", qNo:80, subject:"horticulture", question:"Mango (Mangifera indica), the 'king of fruits', belongs to the family:", options:["Rutaceae", "Musaceae", "Anacardiaceae", "Sapotaceae"], correct:2, explanation:"Mango belongs to the family Anacardiaceae (the cashew family). Citrus belongs to Rutaceae, banana to Musaceae and sapota to Sapotaceae. Mango is a climacteric fruit and the most widely grown fruit crop of India." },
  { id:"gtl_081", qNo:81, subject:"horticulture", question:"Match List-I (Horticultural crop) with List-II (Family) and select the correct combination:", matchTable:{ headers:["List-I (Horticultural crop)", "List-II (Family)"], rows:[["A. Banana", "1. Vitaceae"], ["B. Grape", "2. Rutaceae"], ["C. Citrus", "3. Rubiaceae"], ["D. Coffee", "4. Musaceae"]] }, options:["A-4, B-2, C-1, D-3", "A-4, B-1, C-3, D-2", "A-1, B-4, C-2, D-3", "A-4, B-1, C-2, D-3"], correct:3, explanation:"Banana = Musaceae (4); Grape = Vitaceae (1); Citrus = Rutaceae (2); Coffee = Rubiaceae (3). Hence A-4, B-1, C-2, D-3." },
  { id:"gtl_082", qNo:82, subject:"horticulture", question:"Assertion (A): 'Bahar treatment' is practiced in guava and pomegranate to regulate flowering and the cropping season.\nReason (R): Guava and pomegranate are capable of flowering more than once in a year.", options:["Both A and R are true, and R explains A", "A is true, but R is false", "Both A and R are true, but R does not explain A", "A is false, but R is true"], correct:2, explanation:"Both statements are true, but R is not the full explanation. Bahar treatment works by WITHHOLDING irrigation to rest the tree, then resuming irrigation with manuring to force a synchronous flowering flush in the chosen season. The trees' ability to flower several times makes the choice possible, but the water-stress-then-revival technique is the actual mechanism. Hence R does not explain A." },
  { id:"gtl_083", qNo:83, subject:"horticulture", question:"Which method of propagation is commonly used for raising mango plants true-to-type on a large scale?", options:["Veneer / stone grafting (vegetative)", "Seed (sexual) propagation", "Sowing of stones in situ", "Tissue culture only"], correct:0, explanation:"Mango is propagated vegetatively (commonly by veneer grafting / stone grafting / inarching) to keep the variety true-to-type, because seedling (sexual) propagation gives variable, non-true-to-type plants due to cross-pollination and heterozygosity. Polyembryonic types are an exception." },
  { id:"gtl_084", qNo:84, subject:"horticulture", question:"Consider the following statements:\n1. Tomato, brinjal and chilli belong to the family Solanaceae.\n2. Cabbage and cauliflower belong to the family Cucurbitaceae.\n3. Onion and garlic belong to the family Alliaceae (Amaryllidaceae).\nWhich of the statements are correct?", options:["1 and 2 only", "1 and 3 only", "2 and 3 only", "1, 2 and 3"], correct:1, explanation:"Statements 1 and 3 are correct: tomato, brinjal and chilli are Solanaceae; onion and garlic are Alliaceae/Amaryllidaceae. Statement 2 is FALSE — cabbage and cauliflower (cole crops) belong to Brassicaceae (Cruciferae), NOT Cucurbitaceae (which is the gourd/melon family)." },
  { id:"gtl_085", qNo:85, subject:"horticulture", question:"The spice known as the 'Queen of Spices', and the costliest spice in the world (obtained from flower stigmas), are respectively:", options:["Cinnamon and saffron", "Black pepper and turmeric", "Clove and vanilla", "Cardamom and saffron"], correct:3, explanation:"Cardamom (Elettaria cardamomum) is the 'Queen of Spices' (black pepper is the 'King of Spices'). Saffron, obtained from the dried stigmas of Crocus sativus flowers, is the costliest spice in the world by weight." },
  { id:"gtl_086", qNo:86, subject:"horticulture", question:"To hasten and make uniform the ripening of harvested banana and mango, the plant growth substance/chemical commonly used is:", options:["Maleic hydrazide", "Gibberellic acid (GA3)", "Ethylene / ethephon", "Cycocel (CCC)"], correct:2, explanation:"Ethylene (often supplied as ethephon, which releases ethylene) is the ripening hormone used to trigger fast, uniform ripening of climacteric fruits such as banana and mango. GA3 typically delays ripening/senescence; maleic hydrazide is a growth inhibitor; CCC is a growth retardant." },
  { id:"gtl_087", qNo:87, subject:"horticulture", question:"Tea (Camellia sinensis) and coffee (Coffea arabica) belong, respectively, to the families:", options:["Theaceae and Rubiaceae", "Rubiaceae and Theaceae", "Rutaceae and Rubiaceae", "Theaceae and Malvaceae"], correct:0, explanation:"Tea (Camellia sinensis) belongs to family Theaceae, while coffee (Coffea arabica/robusta) belongs to family Rubiaceae. Both are important plantation beverage crops; tea uses tender leaves and coffee uses the seeds (beans)." },
  { id:"gtl_088", qNo:88, subject:"horticulture", question:"Parthenocarpy refers to:", options:["Development of seed without fertilisation", "Development of fruit without fertilisation, giving seedless fruit", "Formation of multiple embryos in one seed", "Failure of fruit set due to self-incompatibility"], correct:1, explanation:"Parthenocarpy is the development of fruit WITHOUT fertilisation, resulting in seedless fruits (e.g., seedless banana, some grapes and citrus). Development of seed without fertilisation is apomixis; multiple embryos in a seed is polyembryony." },

  // ── FORESTRY / MEDICINAL & AROMATIC (4) ──
  { id:"gtl_089", qNo:89, subject:"forestry", question:"An agroforestry system that combines growing of trees/shrubs with arable crops on the same land is called:", options:["Silvopasture", "Apiculture", "Aquaforestry", "Agrisilviculture"], correct:3, explanation:"Agrisilviculture is the agroforestry system that integrates trees/woody perennials with agricultural (arable) crops on the same unit of land. Silvopasture combines trees with pasture/livestock; agrisilvopasture combines trees, crops and animals together." },
  { id:"gtl_090", qNo:90, subject:"forestry", question:"Match List-I (Tree) with List-II (Botanical name) and select the correct combination:", matchTable:{ headers:["List-I (Tree)", "List-II (Botanical name)"], rows:[["A. Teak", "1. Azadirachta indica"], ["B. Neem", "2. Leucaena leucocephala"], ["C. Subabul", "3. Tectona grandis"], ["D. Eucalyptus", "4. Eucalyptus globulus"]] }, options:["A-1, B-3, C-2, D-4", "A-3, B-1, C-2, D-4", "A-3, B-2, C-1, D-4", "A-3, B-1, C-4, D-2"], correct:1, explanation:"Teak = Tectona grandis (3); Neem = Azadirachta indica (1); Subabul = Leucaena leucocephala (2); Eucalyptus = Eucalyptus globulus (4). Hence A-3, B-1, C-2, D-4." },
  { id:"gtl_091", qNo:91, subject:"forestry", question:"Assertion (A): Social forestry is the practice of raising trees exclusively inside reserved/protected forests by the forest department.\nReason (R): Raising trees on community lands, wastelands and along roads and canals supplies fuel, fodder and small timber to rural people.", options:["A is true, but R is false", "Both A and R are true, but R does not explain A", "A is false, but R is true", "Both A and R are true, and R explains A"], correct:2, explanation:"A is FALSE - social forestry raises trees OUTSIDE traditional forests: on community lands, wastelands, farm boundaries and along roads/canals (not inside reserved forests). R is TRUE - that is exactly what social forestry does, and it relieves pressure on natural forests. Hence A is false but R is true." },
  { id:"gtl_092", qNo:92, subject:"forestry", question:"The medicinal plant Rauwolfia serpentina (Sarpagandha) yields which important alkaloid used to treat hypertension?", options:["Reserpine", "Morphine", "Quinine", "Vincristine"], correct:0, explanation:"Rauwolfia serpentina yields the alkaloid reserpine, used as an antihypertensive and tranquiliser. Quinine comes from Cinchona, morphine from opium poppy (Papaver somniferum), and vincristine/vinblastine from Catharanthus roseus (periwinkle)." },

  // ── GENERAL AGRICULTURE / CURRENT AFFAIRS (6) ──
  { id:"gtl_093", qNo:93, subject:"general-agriculture", question:"The 'Blue Revolution' in India is associated with:", options:["Milk production", "Oilseed production", "Fish and aquaculture production", "Foodgrain production"], correct:2, explanation:"The Blue Revolution refers to the rapid growth of fish and aquaculture production. (White Revolution = milk/Operation Flood; Yellow Revolution = oilseeds; Green Revolution = foodgrains; Golden Revolution = horticulture/honey.)" },
  { id:"gtl_094", qNo:94, subject:"general-agriculture", question:"Match List-I (Revolution) with List-II (Father / leader in India) and select the correct combination:", matchTable:{ headers:["List-I (Revolution)", "List-II (Father / leader in India)"], rows:[["A. Green Revolution", "1. Dr. Verghese Kurien"], ["B. White Revolution", "2. Dr. M.S. Swaminathan"], ["C. Yellow Revolution", "3. Dr. Hiralal Chaudhuri (fish breeding)"], ["D. Blue Revolution", "4. Sam Pitroda"]] }, options:["A-2, B-4, C-1, D-3", "A-2, B-1, C-4, D-3", "A-1, B-2, C-4, D-3", "A-2, B-1, C-3, D-4"], correct:1, explanation:"Green Revolution (foodgrains) = Dr. M.S. Swaminathan (2); White Revolution (milk) = Dr. Verghese Kurien (1); Yellow Revolution (oilseeds) = Sam Pitroda (4); Blue Revolution (fisheries) is associated with the pioneer of induced fish breeding Dr. Hiralal Chaudhuri (3). Hence A-2, B-1, C-4, D-3." },
  { id:"gtl_095", qNo:95, subject:"general-agriculture", question:"Assertion (A): ICAR Foundation Day is celebrated on 16th July.\nReason (R): The Indian Council of Agricultural Research was established on 1st January 1929 at Bengaluru.", options:["A is true, but R is false", "Both A and R are true, but R does not explain A", "Both A and R are true, and R explains A", "A is false, but R is true"], correct:0, explanation:"A is TRUE - ICAR Foundation Day is observed on 16 July. R is FALSE - ICAR was established on 16 July 1929 (as the Imperial Council of Agricultural Research, at New Delhi), not on 1 January 1929 at Bengaluru. Hence A is true but R is false." },
  { id:"gtl_096", qNo:96, subject:"general-agriculture", question:"The 'PM Dhan-Dhaanya Krishi Yojana', announced in the Union Budget 2025-26, is aimed at developing:", options:["Only coastal fishing districts", "Special economic zones for agri-exports", "Metropolitan food-processing hubs", "100 districts having low agricultural productivity"], correct:3, explanation:"Announced in the Union Budget 2025-26, the PM Dhan-Dhaanya Krishi Yojana targets 100 districts with low agricultural productivity, moderate crop intensity and below-average credit availability — benefiting an estimated 1.7 crore farmers, on the model of the Aspirational Districts Programme." },
  { id:"gtl_097", qNo:97, subject:"general-agriculture", question:"Consider the following statements:\n1. The United Nations declared 2023 as the International Year of Millets.\n2. India is the world's largest producer of milk.\n3. The Minimum Support Price (MSP) is currently announced for 23 crops.\nWhich of the statements are correct?", options:["1 and 3 only", "2 and 3 only", "1, 2 and 3", "1 and 2 only"], correct:2, explanation:"All three are correct. The UN declared 2023 as the International Year of Millets on India's proposal (1); India is the world's largest milk producer (2); and the Government announces MSP for 23 mandated crops — 14 kharif, 6 rabi, plus 2 commercial (sugarcane/jute/copra category) crops (3)." },
  { id:"gtl_098", qNo:98, subject:"general-agriculture", question:"The 'Fair and Remunerative Price' (FRP), as distinct from the MSP, is fixed by the Central Government for which crop?", options:["Wheat", "Sugarcane", "Paddy", "Cotton"], correct:1, explanation:"The Fair and Remunerative Price (FRP) is the guaranteed minimum price fixed by the Central Government for SUGARCANE, payable by sugar mills to cane growers under the Sugarcane (Control) Order. Other crops are covered by the MSP system; sugarcane has its own FRP mechanism." },

  // ── COMPUTER APPLICATIONS (1) ──
  { id:"gtl_099", qNo:99, subject:"general-agriculture", question:"In computers, 1 kilobyte (KB) is exactly equal to:", options:["1024 bytes", "1024 bits", "1000 bytes", "100 bytes"], correct:0, explanation:"In the binary system used by computers, 1 kilobyte (KB) = 2 to the power 10 = 1024 bytes, and 1 byte = 8 bits. (The decimal convention of 1 KB = 1000 bytes is used loosely in storage marketing, but the standard computing value is 1024 bytes.)" },

  // ── ENGLISH / GENERAL (1) ──
  { id:"gtl_100", qNo:100, subject:"general-agriculture", question:"Choose the correct one-word substitution for 'a person who studies the science of soils':", options:["Agronomist", "Pomologist", "Entomologist", "Pedologist"], correct:3, explanation:"A pedologist studies the science of soils (pedology). An agronomist studies field-crop production and management, an entomologist studies insects, and a pomologist studies fruit cultivation." },

];
